 {id:"SLK-2043",name:"هدى إبراهيم",phone:"057 422 6951",program:"الاقتصاد السلوكي",track:"التصميم السلوكي",cohort:"—",source:"سلة",owner:"ليان",state:"بانتظار الإسناد",tone:"blue",due:"إسناد اليوم",paid:1500,total:3000},
 {id:"SLK-2042",name:"محمد القحطاني",phone:"059 731 2840",program:"الاقتصاد السلوكي",track:"برنامج الممارس",cohort:"—",source:"دفع مباشر",owner:"مها",state:"تم التواصل",tone:"violet",due:"متابعة غداً",paid:1000,total:3200}
